// Package main implements mass-parallel tokenization of JSONL text shards
// into uint32 binary token shards using a modified YAMIT tokenizer.
//
// It reads JSONL files ({"text": "..."} per line), tokenizes each document,
// and writes binary output shards.  The tokenizer is expected to have been
// generated by build_composite_tokenizer.py, which removes long tokens
// (> max_bytes) directly from the vocabulary and BPE merges.
//
// Output format:
//   - .bin files: flat arrays of little-endian uint32 token IDs
//   - .idx files: little-endian uint64 byte offsets marking document boundaries
//     in the corresponding .bin file (N+1 entries for N documents)
//
// Usage:
//
//	go run . \
//	  --tokenizer ./tokenizer.json \
//	  --input ./raw_data \
//	  --output ./tokenized \
//	  --workers 16 \
//	  --val-fraction 0.005
package main

import (
	"bufio"
	"bytes"
	"encoding/binary"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"math/rand"
	"os"
	"path/filepath"
	"runtime"
	"runtime/pprof"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/sugarme/tokenizer"
	"github.com/sugarme/tokenizer/model/bpe"
	"github.com/sugarme/tokenizer/normalizer"
	"github.com/sugarme/tokenizer/pretokenizer"
	"github.com/sugarme/tokenizer/pretrained"
	"github.com/valyala/fastjson"
	"golang.org/x/text/unicode/norm"
)

// ── Shard writer ─────────────────────────────────────────────────────────

// shardWriter writes tokenized documents to .bin/.idx file pairs.
type shardWriter struct {
	binFile    *os.File
	idxFile    *os.File
	binBuf     *bufio.Writer
	idxBuf     *bufio.Writer
	binScratch []byte
	idxScratch [8]byte
	binOffset  uint64
	docCount   uint64
	tokenCount uint64
}

func newShardWriter(path string) (*shardWriter, error) {
	binPath := path + ".bin"
	idxPath := path + ".idx"

	binFile, err := os.Create(binPath)
	if err != nil {
		return nil, fmt.Errorf("create %s: %w", binPath, err)
	}
	idxFile, err := os.Create(idxPath)
	if err != nil {
		binFile.Close()
		return nil, fmt.Errorf("create %s: %w", idxPath, err)
	}

	w := &shardWriter{
		binFile: binFile,
		idxFile: idxFile,
		binBuf:  bufio.NewWriterSize(binFile, 1<<20), // 1MB buffer
		idxBuf:  bufio.NewWriterSize(idxFile, 1<<16),
	}

	// Write initial offset (0) for first document.
	if err := w.writeIndexOffset(0); err != nil {
		w.Close()
		return nil, err
	}

	return w, nil
}

func (w *shardWriter) writeIndexOffset(off uint64) error {
	binary.LittleEndian.PutUint64(w.idxScratch[:], off)
	_, err := w.idxBuf.Write(w.idxScratch[:])
	return err
}

// writeDocument appends a tokenized document's token IDs to the shard.
func (w *shardWriter) writeDocument(tokenIDs []int) error {
	nBytes := len(tokenIDs) * 4
	if cap(w.binScratch) < nBytes {
		w.binScratch = make([]byte, nBytes)
	}
	buf := w.binScratch[:nBytes]
	for i, id := range tokenIDs {
		binary.LittleEndian.PutUint32(buf[i*4:], uint32(id))
	}
	if _, err := w.binBuf.Write(buf); err != nil {
		return err
	}
	w.binOffset += uint64(len(tokenIDs)) * 4
	w.tokenCount += uint64(len(tokenIDs))
	w.docCount++

	// Write end offset for this document.
	return w.writeIndexOffset(w.binOffset)
}

func (w *shardWriter) Close() error {
	var errs []error
	if err := w.binBuf.Flush(); err != nil {
		errs = append(errs, err)
	}
	if err := w.idxBuf.Flush(); err != nil {
		errs = append(errs, err)
	}
	if err := w.binFile.Close(); err != nil {
		errs = append(errs, err)
	}
	if err := w.idxFile.Close(); err != nil {
		errs = append(errs, err)
	}
	if len(errs) > 0 {
		return errs[0]
	}
	return nil
}

// ── JSONL reading ────────────────────────────────────────────────────────

type jsonlRecord struct {
	Text string `json:"text"`
}

const fastPathVerifyDocs = 8

type addedTokenEntry struct {
	content string
	id      int
}

type fastEncoder struct {
	model        *bpe.BPE
	splitPattern normalizer.Pattern
	byteLevel    *pretokenizer.ByteLevel
	byteChar     [256]string
	normalizeNFC bool
	verifyBudget int
	addedTokens  []addedTokenEntry // sorted longest-first
}

func buildFastEncoder(tk *tokenizer.Tokenizer) (*fastEncoder, string) {
	model, ok := tk.GetModel().(*bpe.BPE)
	if !ok {
		return nil, "model is not BPE"
	}

	seq, ok := tk.GetPreTokenizer().(*pretokenizer.Sequence)
	if !ok {
		return nil, "pretokenizer is not Sequence"
	}

	pretoks := seq.PreTokenizers()
	if len(pretoks) != 2 {
		return nil, fmt.Sprintf("pretokenizer sequence len=%d (need 2)", len(pretoks))
	}

	split, ok := pretoks[0].(*pretokenizer.Split)
	if !ok {
		return nil, "first pretokenizer is not Split"
	}
	if split.Invert {
		return nil, "split invert=true unsupported"
	}
	if split.Behavior != normalizer.IsolatedBehavior {
		return nil, "split behavior is not Isolated"
	}

	bl, ok := pretoks[1].(*pretokenizer.ByteLevel)
	if !ok {
		return nil, "second pretokenizer is not ByteLevel"
	}
	if bl.UseRegex {
		return nil, "bytelevel use_regex=true unsupported"
	}

	normer := tk.GetNormalizer()
	normalizeNFC := false
	if normer != nil {
		if _, ok := normer.(*normalizer.NFC); ok {
			normalizeNFC = true
		} else {
			return nil, fmt.Sprintf("normalizer type %T unsupported", normer)
		}
	}

	// Collect added tokens for splitting before BPE.
	addedVocab := tk.GetAddedVocab()
	entries := make([]addedTokenEntry, 0, len(addedVocab))
	for content, id := range addedVocab {
		entries = append(entries, addedTokenEntry{content, id})
	}
	// Sort longest-first for greedy matching.
	sort.Slice(entries, func(i, j int) bool {
		if len(entries[i].content) != len(entries[j].content) {
			return len(entries[i].content) > len(entries[j].content)
		}
		return entries[i].content < entries[j].content
	})

	fe := &fastEncoder{
		model:        model,
		splitPattern: split.Pattern,
		byteLevel:    bl,
		normalizeNFC: normalizeNFC,
		verifyBudget: fastPathVerifyDocs,
		addedTokens:  entries,
	}
	for i := 0; i < 256; i++ {
		fe.byteChar[i] = pretokenizer.BytesChar[byte(i)]
	}

	return fe, ""
}

func (f *fastEncoder) byteLevelMap(s string) string {
	if len(s) == 0 {
		return s
	}
	var b strings.Builder
	b.Grow(len(s) * 2)
	for i := 0; i < len(s); i++ {
		b.WriteString(f.byteChar[s[i]])
	}
	return b.String()
}

// encodeBPESegment runs the regex-split + byte-level-map + BPE pipeline on
// a segment of text that is known to contain no added tokens.
func (f *fastEncoder) encodeBPESegment(segment string, dst []int) []int {
	matches := f.splitPattern.FindMatches(segment)
	for _, m := range matches {
		start := m.Offsets[0]
		end := m.Offsets[1]
		if start < 0 || end > len(segment) || start >= end {
			continue
		}

		piece := segment[start:end]
		if f.byteLevel.AddPrefixSpace && !strings.HasPrefix(piece, " ") {
			piece = " " + piece
		}

		mapped := f.byteLevelMap(piece)
		toks := f.model.TokenizeWithCache(mapped)
		for _, tok := range toks {
			dst = append(dst, tok.Id)
		}
	}
	return dst
}

func (f *fastEncoder) encodeIntoIDs(text string, dst []int) ([]int, bool, error) {
	normText := text
	if f.normalizeNFC {
		normText = norm.NFC.String(text)
	}

	dst = dst[:0]

	if len(f.addedTokens) == 0 {
		dst = f.encodeBPESegment(normText, dst)
		return dst, true, nil
	}

	// Split text around added tokens, greedy longest-match scan.
	remaining := normText
	for len(remaining) > 0 {
		bestIdx := -1
		bestPos := -1
		for i, at := range f.addedTokens {
			pos := strings.Index(remaining, at.content)
			if pos != -1 && (bestPos == -1 || pos < bestPos) {
				bestPos = pos
				bestIdx = i
				break // sorted longest-first, first hit at this pos is best
			}
		}
		if bestIdx == -1 {
			// No more added tokens — BPE-encode the rest.
			dst = f.encodeBPESegment(remaining, dst)
			break
		}

		// BPE-encode the text before the added token.
		if bestPos > 0 {
			dst = f.encodeBPESegment(remaining[:bestPos], dst)
		}
		// Emit the added token ID directly.
		dst = append(dst, f.addedTokens[bestIdx].id)
		remaining = remaining[bestPos+len(f.addedTokens[bestIdx].content):]
	}

	return dst, true, nil
}

func equalIntSlices(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func readJSONLFile(path string) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var texts []string
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0), 10*1024*1024) // 10MB max line
	for scanner.Scan() {
		var rec jsonlRecord
		if err := json.Unmarshal(scanner.Bytes(), &rec); err != nil {
			continue // skip malformed lines
		}
		if len(strings.TrimSpace(rec.Text)) > 0 {
			texts = append(texts, rec.Text)
		}
	}
	return texts, scanner.Err()
}

// ── Worker pool ──────────────────────────────────────────────────────────

type tokenizeResult struct {
	inputPath   string
	relPath     string
	trainTokens int
	trainDocs   int
	valTokens   int
	valDocs     int
	elapsed     time.Duration
	err         error
}

type tokenizeJob struct {
	inputPath    string
	relPath      string
	trainOutPath string
	valOutPath   string
	rngSeed      int64
}

func tokenizeJSONLSplit(
	path string,
	trainPath string,
	valPath string,
	valFraction float64,
	rng *rand.Rand,
	tk *tokenizer.Tokenizer,
	fast *fastEncoder,
) (trainDocs, trainTokens, valDocs, valTokens int, err error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, 0, 0, 0, err
	}

	trainWriter, err := newShardWriter(trainPath)
	if err != nil {
		return 0, 0, 0, 0, err
	}
	valWriter, err := newShardWriter(valPath)
	if err != nil {
		_ = trainWriter.Close()
		return 0, 0, 0, 0, err
	}

	fastIDs := make([]int, 0, 256)
	var fjParser fastjson.Parser

	encodeSlow := func(text string) ([]int, error) {
		enc, err := tk.EncodeSingle(text)
		if err != nil {
			return nil, err
		}
		return enc.Ids, nil
	}

	for len(data) > 0 {
		nl := bytes.IndexByte(data, '\n')
		var line []byte
		if nl >= 0 {
			line = data[:nl]
			data = data[nl+1:]
		} else {
			line = data
			data = nil
		}
		if len(line) == 0 {
			continue
		}

		v, err := fjParser.ParseBytes(line)
		if err != nil {
			continue
		}
		textBytes := v.GetStringBytes("text")
		if len(textBytes) == 0 {
			continue
		}
		text := string(textBytes)

		var ids []int
		if fast != nil {
			var usedFast bool
			fastIDs, usedFast, err = fast.encodeIntoIDs(text, fastIDs)
			if err != nil {
				_ = trainWriter.Close()
				_ = valWriter.Close()
				return 0, 0, 0, 0, err
			}
			if usedFast {
				ids = fastIDs
				if fast.verifyBudget > 0 {
					slowIDs, slowErr := encodeSlow(text)
					if slowErr != nil {
						log.Printf("WARNING: fast-path verify slow-encode failed in %s: %v", path, slowErr)
					} else if !equalIntSlices(ids, slowIDs) {
						log.Printf("WARNING: fast-path mismatch in %s; disabling fast path for worker", path)
						fast = nil
						ids = slowIDs
					} else {
						fast.verifyBudget--
					}
				}
			}
		}

		if ids == nil {
			ids, err = encodeSlow(text)
			if err != nil {
				log.Printf("WARNING: failed to encode document in %s: %v", path, err)
				continue
			}
		}

		// Route each document to train or val.
		if rng.Float64() < valFraction {
			if err := valWriter.writeDocument(ids); err != nil {
				_ = trainWriter.Close()
				_ = valWriter.Close()
				return 0, 0, 0, 0, err
			}
			valDocs++
			valTokens += len(ids)
		} else {
			if err := trainWriter.writeDocument(ids); err != nil {
				_ = trainWriter.Close()
				_ = valWriter.Close()
				return 0, 0, 0, 0, err
			}
			trainDocs++
			trainTokens += len(ids)
		}
	}

	if err := trainWriter.Close(); err != nil {
		_ = valWriter.Close()
		return 0, 0, 0, 0, err
	}
	if err := valWriter.Close(); err != nil {
		return 0, 0, 0, 0, err
	}

	// Remove empty shard files.
	if trainDocs == 0 {
		os.Remove(trainPath + ".bin")
		os.Remove(trainPath + ".idx")
	}
	if valDocs == 0 {
		os.Remove(valPath + ".bin")
		os.Remove(valPath + ".idx")
	}

	return trainDocs, trainTokens, valDocs, valTokens, nil
}

func tokenizeWorker(
	tokenizerPath string,
	bpeCacheCapacity int,
	valFraction float64,
	jobs <-chan tokenizeJob,
	results chan<- tokenizeResult,
) {
	var (
		tk      *tokenizer.Tokenizer
		fast    *fastEncoder
		loadErr error
	)

	for job := range jobs {
		if tk == nil && loadErr == nil {
			tk, loadErr = pretrained.FromFile(tokenizerPath)
			if loadErr == nil && bpeCacheCapacity >= 0 {
				if m, ok := tk.GetModel().(*bpe.BPE); ok {
					if bpeCacheCapacity == 0 {
						m.Cache = nil
					} else {
						m.Cache = bpe.NewCache(bpeCacheCapacity)
					}
				}
			}
			if loadErr == nil {
				var reason string
				fast, reason = buildFastEncoder(tk)
				if fast != nil {
					log.Printf("Worker fast path enabled (verify_docs=%d)", fast.verifyBudget)
				} else {
					log.Printf("Worker fast path disabled: %s", reason)
				}
			}
		}

		if loadErr != nil {
			results <- tokenizeResult{
				inputPath: job.inputPath,
				relPath:   job.relPath,
				err:       fmt.Errorf("load tokenizer: %w", loadErr),
			}
			continue
		}

		// Create output directories for both splits.
		if err := os.MkdirAll(filepath.Dir(job.trainOutPath), 0o755); err != nil {
			results <- tokenizeResult{
				inputPath: job.inputPath,
				relPath:   job.relPath,
				err:       err,
			}
			continue
		}
		if err := os.MkdirAll(filepath.Dir(job.valOutPath), 0o755); err != nil {
			results <- tokenizeResult{
				inputPath: job.inputPath,
				relPath:   job.relPath,
				err:       err,
			}
			continue
		}

		rng := rand.New(rand.NewSource(job.rngSeed))
		t0 := time.Now()
		trDocs, trToks, vDocs, vToks, err := tokenizeJSONLSplit(
			job.inputPath, job.trainOutPath, job.valOutPath,
			valFraction, rng, tk, fast,
		)
		dt := time.Since(t0)
		results <- tokenizeResult{
			inputPath:   job.inputPath,
			relPath:     job.relPath,
			trainTokens: trToks,
			trainDocs:   trDocs,
			valTokens:   vToks,
			valDocs:     vDocs,
			elapsed:     dt,
			err:         err,
		}
	}
}

// ── Main ─────────────────────────────────────────────────────────────────

func main() {
	tokenizerPath := flag.String("tokenizer", "", "Path to tokenizer.json")
	inputDir := flag.String("input", "", "Input directory with JSONL shards (searched recursively)")
	outputDir := flag.String("output", "", "Output directory for .bin/.idx shards")
	workers := flag.Int("workers", 0, "Number of worker goroutines (default: NumCPU)")
	valFraction := flag.Float64("val-fraction", 0.005, "Fraction of shards to reserve for validation")
	bpeCacheCapacity := flag.Int("bpe-cache-capacity", -1, "BPE cache capacity override per worker (-1 keeps tokenizer default)")
	cpuProfile := flag.String("cpu-profile", "", "Optional path to write CPU profile")
	flag.Parse()

	if *tokenizerPath == "" || *inputDir == "" || *outputDir == "" {
		flag.Usage()
		os.Exit(1)
	}
	if *workers <= 0 {
		*workers = runtime.NumCPU()
	}

	if *cpuProfile != "" {
		f, err := os.Create(*cpuProfile)
		if err != nil {
			log.Fatalf("Failed to create cpu profile file: %v", err)
		}
		if err := pprof.StartCPUProfile(f); err != nil {
			f.Close()
			log.Fatalf("Failed to start cpu profile: %v", err)
		}
		defer func() {
			pprof.StopCPUProfile()
			_ = f.Close()
			log.Printf("CPU profile written to %s", *cpuProfile)
		}()
	}

	startTime := time.Now()

	// Load tokenizer.
	log.Printf("Loading tokenizer from %s", *tokenizerPath)
	tk, err := pretrained.FromFile(*tokenizerPath)
	if err != nil {
		log.Fatalf("Failed to load tokenizer: %v", err)
	}
	log.Printf("Vocabulary size: %d", tk.GetVocabSize(true))
	if m, ok := tk.GetModel().(*bpe.BPE); ok {
		defaultCap := 0
		if m.Cache != nil {
			defaultCap = m.Cache.Capacity
		}
		if *bpeCacheCapacity >= 0 {
			log.Printf("BPE cache capacity override: %d (default=%d)", *bpeCacheCapacity, defaultCap)
		} else {
			log.Printf("BPE cache capacity default: %d", defaultCap)
		}
	} else if *bpeCacheCapacity >= 0 {
		log.Printf("WARNING: --bpe-cache-capacity ignored (model is not BPE)")
	}

	// Find all JSONL files.
	var jsonlFiles []string
	err = filepath.Walk(*inputDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() && strings.HasSuffix(path, ".jsonl") {
			jsonlFiles = append(jsonlFiles, path)
		}
		return nil
	})
	if err != nil {
		log.Fatalf("Failed to walk input directory: %v", err)
	}
	sort.Strings(jsonlFiles)
	log.Printf("Found %d JSONL files", len(jsonlFiles))

	if len(jsonlFiles) == 0 {
		log.Fatal("No .jsonl files found")
	}

	effectiveWorkers := *workers
	if effectiveWorkers > len(jsonlFiles) {
		effectiveWorkers = len(jsonlFiles)
	}
	if effectiveWorkers < 1 {
		effectiveWorkers = 1
	}
	if effectiveWorkers != *workers {
		log.Printf("Workers clamped to %d (requested=%d, shards=%d)", effectiveWorkers, *workers, len(jsonlFiles))
	}

	// Create output directories.
	trainDir := filepath.Join(*outputDir, "train")
	valDir := filepath.Join(*outputDir, "val")
	os.MkdirAll(trainDir, 0o755)
	os.MkdirAll(valDir, 0o755)

	// Val split is per-document: each document is randomly assigned to val
	// with probability valFraction, so every source gets representation.
	log.Printf("Val split: %.2f%% of documents per shard (per-document)", *valFraction*100)

	// Launch worker pool.
	jobs := make(chan tokenizeJob, effectiveWorkers*2)
	results := make(chan tokenizeResult, effectiveWorkers*2)

	var wg sync.WaitGroup
	for i := 0; i < effectiveWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			tokenizeWorker(
				*tokenizerPath,
				*bpeCacheCapacity,
				*valFraction,
				jobs,
				results,
			)
		}()
	}

	// Feed jobs.
	go func() {
		for i, path := range jsonlFiles {
			relPath, _ := filepath.Rel(*inputDir, path)
			relDir := filepath.Dir(relPath)
			shardName := strings.TrimSuffix(filepath.Base(path), ".jsonl")

			jobs <- tokenizeJob{
				inputPath:    path,
				relPath:      relPath,
				trainOutPath: filepath.Join(trainDir, relDir, shardName),
				valOutPath:   filepath.Join(valDir, relDir, shardName),
				rngSeed:      42 + int64(i),
			}
		}
		close(jobs)
	}()

	// Collect results in a separate goroutine.
	go func() {
		wg.Wait()
		close(results)
	}()

	// Process results.
	var totalTokens uint64
	var totalDocs uint64
	var trainTokens, valTokens uint64
	var errorCount int
	shardsCompleted := 0

	for result := range results {
		if result.err != nil {
			log.Printf("ERROR processing %s: %v", result.inputPath, result.err)
			errorCount++
			continue
		}
		shardTokens := result.trainTokens + result.valTokens
		shardDocs := result.trainDocs + result.valDocs
		totalTokens += uint64(shardTokens)
		totalDocs += uint64(shardDocs)
		trainTokens += uint64(result.trainTokens)
		valTokens += uint64(result.valTokens)
		shardsCompleted++

		// Per-shard speed.
		shardTokSec := float64(0)
		if result.elapsed > 0 {
			shardTokSec = float64(shardTokens) / result.elapsed.Seconds()
		}
		// Aggregate speed.
		wallElapsed := time.Since(startTime).Seconds()
		aggTokSec := float64(0)
		if wallElapsed > 0 {
			aggTokSec = float64(totalTokens) / wallElapsed
		}
		log.Printf("%s — %d docs (%d train, %d val), %dk tok, %.1fM tok/s (agg %.1fM tok/s, %d/%d shards)",
			result.relPath, shardDocs, result.trainDocs, result.valDocs,
			shardTokens/1000, shardTokSec/1e6,
			aggTokSec/1e6, shardsCompleted, len(jsonlFiles))
	}

	elapsed := time.Since(startTime)
	tTotal := totalTokens
	dTotal := totalDocs

	log.Printf("")
	log.Printf("═══════════════════════════════════════════════════")
	log.Printf("Tokenization complete in %v", elapsed.Round(time.Second))
	log.Printf("  Total:  %d documents, %d tokens", dTotal, tTotal)
	log.Printf("  Train:  %d tokens", trainTokens)
	log.Printf("  Val:    %d tokens", valTokens)
	log.Printf("  Errors: %d", errorCount)
	if elapsed.Seconds() > 0 {
		log.Printf("  Speed:  %.0f tokens/sec", float64(tTotal)/elapsed.Seconds())
	}
	log.Printf("═══════════════════════════════════════════════════")

	// Write tokenization metadata.
	metaPath := filepath.Join(*outputDir, "tokenize_meta.json")
	meta := map[string]interface{}{
		"tokenizer":          *tokenizerPath,
		"vocab_size":         tk.GetVocabSize(true),
		"bpe_cache_capacity": *bpeCacheCapacity,
		"total_tokens":       tTotal,
		"total_docs":         dTotal,
		"train_tokens":       trainTokens,
		"val_tokens":         valTokens,
		"val_fraction":       *valFraction,
		"workers":            effectiveWorkers,
		"elapsed_secs":       elapsed.Seconds(),
		"errors":             errorCount,
	}
	metaJSON, _ := json.MarshalIndent(meta, "", "  ")
	os.WriteFile(metaPath, metaJSON, 0o644)
	log.Printf("Metadata written to %s", metaPath)
}
